"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9924"],{4114(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>h,assets:()=>d});var a=JSON.parse('{"id":"how-to/dashboard","title":"Getting started with the dashboard and rules","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/dashboard.md","sourceDirName":"how-to","slug":"/how-to/dashboard","permalink":"/personal-av-docs/docs/how-to/dashboard","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/dashboard.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Getting started with the dashboard and rules","sidebar_label":"Getting started with the dashboard and r","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/dashboard","format":"md"}}'),o=n(4848),i=n(8453);let s={title:"Getting started with the dashboard and rules",sidebar_label:"Getting started with the dashboard and r",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/dashboard",format:"md"},r,d={},h=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/av/howto/dashboard",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"Getting started with the dashboard and rules\nThis tutorial describes how to detect a change on a system and trigger an action to automate monitoring of your device fleet, and how to visualize your operational KPI with the dashboard.\nThe use case in the first section is an embedded application tutorial for devices like the\nHL8518-S\n. If you use a different application, you can adapt the rules and the dashboard to your own use case.\n1 /\nUse case\n2 /\nRules Creation\n3 /\nDashboard Design\nUse case Description\nTo exploit data from the fleet, organizations often define a\ncustom dashboard\nin AirVantage, with visual widgets and alerts.\nThe dashboard tutorial described later on this page could apply to a use case such as the following:\nFor a fleet of refrigerated trucks, containers must be monitored via AirVantage to ensure that temperature-sensitive perishable cargo (blood, chilled food\u2026) remains within safety parameters:\nwhen the truck\u2019s container door is closed, the refrigeration system (fan, compressor) must operate\nan alarm sensor checks CO2 levels to detect fire or human presence in the container\nEvery two days, the fan is physically checked by a maintenance engineer.\nApplication description\nEach truck is fitted with a device that sends the following data to AirVantage:\nVariables:\ndoorOpen (boolean), true if the door is opened.\nTemperature (float), just the temperature value.\nFanDuration (int between 0 and 3200 minutes): duration in minutes when the fan works\nAlarm (boolean): status of the alarm system (on/off). The CO2 rate is analyzed to raise an alert.\nFan (Boolean): status of fan (on/off).\nCO2 Alert (Boolean): alert sent if CO2 is too high (can be sent only if alarm is on).\nSettings:\ntargetTemp (float, by default is -5): defines the targeted temperature. When the temperature is reached, the fan stops.\nAnd AirVantage must be able to send the following Commands to the truck\u2019s  device:\nArm CO2 Alarm/Disarm CO2 Alarm (Arm command checks the door is closed).\nStart/Stop Fan (startFan checks FanDuration < 3000). Fan is automatically stopped when temp <= targetTemp.\nBuilding the rules\nRules must be created to detect any change about your system and automate action when a given change has been detected. Thus, you can highlight a specific behavior of your system and fix the problem.\nA rule must contain a:\nName\nList of conditions\nList of actions to trigger like notifying a user by email, acting on the system, or pushing an alert to your application.\nThis can be implemented by defining the following rules:\nIf\ntemp > 0\nthen\nsend command startFan\nIf\ntemp > 10\nthen\nsend email\nIf\nfanDuration > 3000\nthen\nsend email\nIf\ndoorOpen is false and alarm is false\nthen\nsend command wind alarm\nCreate the rules\nIn order to simplify the creation of a rule, a set of templates is available to focus on what you want to monitor. If you want to use any of the available data and operator, choose\nCustom\n:\nCommunication status change\n: defines a condition based on the system (name, label, offer or communication).\nData sent to AirVantage\n: defines a condition based on a data from the device.\nMonthly usage limit exceeded\n: monthly data exchanged is greater than a given number of MB\u2019s.\nUsage limit exceeded\n: defines a condition based on any connectivity metrics (voice duration, nb of SMS, etc.).\nUsage status change\n: defines a condition based on the data plan status.\nCustom\n: defines a condition with one among all the available conditions.\nLet\u2019s create the following rule\nIf temp > 0 then send command startFan\n:\nNavigate to\nConfigure\n>\nAlert Rules\n.\nClick on the + button.\nPopulate the name and description. The name will be used in the interface and the connectors to show the event raised by this rule.\nClick on the\nData sent to AirVantage\ntemplate.\nSelect your application which sends the data you want to monitor.\nSelect the\nTemperature\ndata.\nBy default, the last raw data value sent by the device is used but you can change to aggregated data.\nSelect the operand\nis greater than\nand fill the right value.\nSelect the action\nSend Command\nand select the startFan command.\nSelect the application and the command with the parameters.\nClick on\nSave\n.\nThis rule creates a\nSend Command\noperation which is executed as soon as the device becomes connected with AirVantage.\nYou can repeat these steps for each rule you want to create.\nThe command will not be sent again when the conditions are no longer met. However, the\nAdd label\naction will remove the label when the conditions are no longer met.\nView the events\nEach rule will raise an event (an alert) each time the condition is met. The event can be viewed in three pages:\nTop Bar Notification\nIn the top bar, a quick notification when an event has been raised. Click on the event to see more details about it.\nSystem\u2019s Alert State\nIn the table in\nMonitor\n>\nSystems\n, the systems are identified in error if a problem has been detected by a rule as long as the problem is still raised.\nAlerts History\nIn\nMonitor\n>\nAlerts\n, all the current alerts are listed for troubleshooting. If you click on an alert, a dialog box shows you the details of the alert.\nBuilding the dashboard\nNow that you can detect system changes, you may want to have a single dashboard to show KPIs about your fleet and to drill down to a system\u2019s dashboard.\nFollow the steps below to define a dashboard for a system:\nNavigate to\nMonitor\n>\nSystem\n.\nChoose the referenced system you used to build your dashboard (all the system will share this dashboard).\nClick on the line to drill down into the system\u2019s view.\nYou can add or remove a widget, or change the size of some widgets by clicking on the top bar button. For more information about the dashboard, click\nhere\n.\nFollow the steps below to customize your fleet dashboard:\nClick on the top-left icon:\nProceed similarly like for the system dashboard described above. By default, the widget shows the data aggregated for the entire fleet, but you can select a specific system.\nThis dashboard contains the following widgets:\nFirst Line (from left to right)\nSingle Value Widget\n: Temperature (raw value), Unit: \xb0C and precision set to 0, title: Target Temperature.\nGauge widget\n: Current Temp (raw value), Precision: 2, minimum: -15, maximum: 20, threshold 1: -1, threshold 2: 5.\nMap Widget\n: No configuration required - shows truck location.\nSingle Value Widget\n: Fan state (raw value), two rules to set an icon:\nAlarm State Widget\n: See the configuration on the right.\nSecond Line (from left to right)\nCombo Chart Widget\n: Fan use duration with chart option to show the period browser (drop-down list). Select SUM aggregation and configure the option as shown in the screenshot on the right.\nShow the data configuration and select histogram type in the Series section; check\nCumulated\n.\nCommand widget\n: Based on the fan and alarm commands above.\nAdd a new button for each command you want to access on a given line.\nAdd a new tab if you want to add a new line.\nConfigure the command associated to the button by selecting the application which manages the command and the command with the parameter. If no parameter is selected, all of the mandatory parameters will be required by the user.\nThird Line:\nAlert history\n: This widget requires no configuration.\nNext Step\nOnce your system communicates correctly with AirVantage and data values can be browsed and displayed, you may want to get them into your specific application. Have a look to our\nAirVantage API\nto learn how to use these API to build powerful applications for your customer."})]})}function c(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(6540);let o={},i=a.createContext(o);function s(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);